"""Supplier B's share of apparel lines and its own return rate, Q3 FY24 and Q2 FY26."""
import csv
from pathlib import Path

ORDERS = Path("engagements/acme-review-test/corpus/orders/orders_export.csv")
Q3_FY24 = {"2024-07", "2024-08", "2024-09"}
Q2_FY26 = {"2026-04", "2026-05", "2026-06"}


def month_of(d):
    if "/" in d:
        dd, mm, yy = d.split("/")
        return f"{yy}-{mm}"
    return d[:7]


with ORDERS.open(encoding="utf-8", newline="") as f:
    rows = list(csv.DictReader(f))
seen, lines = set(), []
for r in rows:
    k = (r["order_id"], r["line_no"])
    if k not in seen:
        seen.add(k)
        lines.append(r)
print(f"rows raw {len(rows)} -> deduplicated {len(lines)}")
apparel = [r for r in lines if r["category"] == "Apparel" and r["sku"] != "BND-001"]
for label, q in (("Q3 FY24", Q3_FY24), ("Q2 FY26", Q2_FY26)):
    sel = [r for r in apparel if month_of(r["order_date"]) in q]
    b = [r for r in sel if r["supplier"] == "Supplier B"]
    b_ret = sum(r["returned"] == "Y" for r in b)
    print(f"{label}: Supplier B share {100*len(b)/len(sel):.1f}% of {len(sel)} apparel lines; "
          f"Supplier B return rate {100*b_ret/len(b):.1f}% ({b_ret}/{len(b)})")
    reasons = {}
    for r in b:
        if r["returned"] == "Y":
            reasons[r["return_reason"]] = reasons.get(r["return_reason"], 0) + 1
    print(f"  Supplier B return reasons: {reasons}")

